/**
 * @planks("the app is loaded")
 * @planks("the todo list is empty")
 * @planks("I have a todo titled {string}")
 * @planks("I have a completed todo titled {string}")
 * @planks("I have todos: {string}")
 * @planks("I have todos: {string}, {string}")
 * @planks("I have todos: {string}, {string}, {string}")
 * @planks("I have an active todo titled {string}")
 * @planks("I am editing the todo {string}")
 * @planks("I type {string} into the new-todo input")
 * @planks("I press Enter")
 * @planks("I press Enter in the edit input")
 * @planks("I press Escape in the edit input")
 * @planks("I click the toggle checkbox for {string}")
 * @planks("I click the {string} checkbox")
 * @planks("I click {string}")
 * @planks("I complete all todos individually")
 * @planks("I double-click the label for {string}")
 * @planks("I change the edit input value to {string}")
 * @planks("the edit input loses focus")
 * @planks("I click the destroy button for {string}")
 * @planks("I navigate to {string}")
 * @planks("I complete the todo {string}")
 * @planks("I reload the app")
 * @planks("{string} should be hidden")
 * @planks("I should see {int} todo in the list")
 * @planks("I should see {int} todos in the list")
 * @planks("there should be {int} todo in the list")
 * @planks("the new-todo input should be cleared")
 * @planks("the todo list should still be empty")
 * @planks("the todo list should be empty")
 * @planks("I should see a todo with title {string}")
 * @planks("the {string} todo should have class {string}")
 * @planks("the {string} todo should have its {string} property set")
 * @planks("the {string} todo should not have class {string}")
 * @planks("all todos should be marked completed")
 * @planks("the {string} checkbox should be checked")
 * @planks("the {string} button should be hidden")
 * @planks("the {string} todo item should have class {string}")
 * @planks("the edit input for {string} should be focused")
 * @planks("the {string} todo item should not have class {string}")
 * @planks("the todo-count should show {string}")
 * @planks("the filter link for {string} should have class {string}")
 * @planks("localStorage should contain a key matching {string}")
 * @planks("localStorage todo data should include fields {string}")
 * @planks("localStorage todo data should include fields {string}, {string}, {string}")
 */
(function () {
  'use strict';

  var STORAGE_KEY = 'todos-shipshape';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  // ─── Model ──────────────────────────────────────────────────────────────────

  function getTodos() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (e) {
      return [];
    }
  }

  function setTodos(todos) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function genId() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  }

  // ─── View ───────────────────────────────────────────────────────────────────

  function render() {
    var todos = getTodos();
    var list = document.querySelector('.todo-list');
    var main = document.querySelector('.main');
    var footer = document.querySelector('.footer');
    var todoCount = document.querySelector('.todo-count');
    var toggleAll = document.getElementById('toggle-all');
    var clearCompleted = document.querySelector('.clear-completed');

    // Clear list
    list.innerHTML = '';

    var route = getRoute();

    for (var i = 0; i < todos.length; i++) {
      var todo = todos[i];

      // Filter
      if (route === 'active' && todo.completed) continue;
      if (route === 'completed' && !todo.completed) continue;

      var li = document.createElement('li');
      if (todo.completed) li.classList.add('completed');

      li.setAttribute('data-id', todo.id);
      li.innerHTML =
        '<div class="view">' +
          '<input class="toggle" type="checkbox" ' + (todo.completed ? 'checked' : '') + '>' +
          '<label>' + escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + escapeAttr(todo.title) + '">';

      list.appendChild(li);
    }

    // Show/hide main & footer
    var hasTodos = todos.length > 0;
    main.style.display = hasTodos ? 'block' : 'none';
    footer.style.display = hasTodos ? 'block' : 'none';

    // Count
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' +
      (activeCount === 1 ? 'item' : 'items') + ' left';

    // Toggle-all
    toggleAll.checked = hasTodos && todos.every(function (t) { return t.completed; });

    // Clear completed
    var completedCount = todos.filter(function (t) { return t.completed; }).length;
    clearCompleted.style.display = completedCount > 0 ? 'block' : 'none';
  }

  function getRoute() {
    var hash = window.location.hash || '#/';
    hash = hash.replace(/^#!/, '#/');
    var match = hash.match(/^#\/(\w*)/);
    var route = match ? match[1] : '';
    updateFilterLinks(route);
    return route;
  }

  function updateFilterLinks(route) {
    var links = document.querySelectorAll('.filters a');
    for (var i = 0; i < links.length; i++) {
      var a = links[i];
      var href = a.getAttribute('href');
      var linkRoute = href.replace(/^#\//, '');
      if (linkRoute === route || (!route && linkRoute === '')) {
        a.classList.add('selected');
      } else {
        a.classList.remove('selected');
      }
    }
  }

  function escapeHtml(str) {
    return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  }

  function escapeAttr(str) {
    return str.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  }

  // ─── Controller ─────────────────────────────────────────────────────────────

  function addTodo(title) {
    title = title.trim();
    if (!title) return;
    var todos = getTodos();
    todos.push({ id: genId(), title: title, completed: false });
    setTodos(todos);
    render();
  }

  function removeTodo(id) {
    var todos = getTodos();
    var idx = -1;
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) { idx = i; break; }
    }
    if (idx === -1) return;
    todos.splice(idx, 1);
    setTodos(todos);
    render();
  }

  function toggleTodo(id) {
    var todos = getTodos();
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].completed = !todos[i].completed;
        break;
      }
    }
    setTodos(todos);
    render();
  }

  function toggleAll(checked) {
    var todos = getTodos();
    for (var i = 0; i < todos.length; i++) {
      todos[i].completed = checked;
    }
    setTodos(todos);
    render();
  }

  function clearCompleted() {
    var todos = getTodos();
    todos = todos.filter(function (t) { return !t.completed; });
    setTodos(todos);
    render();
  }

  function updateTodo(id, title) {
    title = title.trim();
    var todos = getTodos();
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        if (!title) {
          todos.splice(i, 1);
        } else {
          todos[i].title = title;
        }
        break;
      }
    }
    setTodos(todos);
    render();
  }

  // ─── Events ─────────────────────────────────────────────────────────────────

  document.addEventListener('DOMContentLoaded', function () {
    render();

    // New todo
    var newTodo = document.querySelector('.new-todo');
    newTodo.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.keyCode === ENTER_KEY) {
        addTodo(this.value);
        this.value = '';
      }
    });

    // List events via delegation
    var list = document.querySelector('.todo-list');
    list.addEventListener('change', function (e) {
      if (e.target.classList.contains('toggle')) {
        var li = e.target.closest('li');
        if (li) toggleTodo(li.getAttribute('data-id'));
      }
    });

    list.addEventListener('click', function (e) {
      if (e.target.classList.contains('destroy')) {
        var li = e.target.closest('li');
        if (li) removeTodo(li.getAttribute('data-id'));
      }
    });

    list.addEventListener('dblclick', function (e) {
      var label = e.target.closest('label');
      if (!label) return;
      var li = label.closest('li');
      if (!li) return;
      li.classList.add('editing');
      var editInput = li.querySelector('.edit');
      editInput.focus();
      editInput.value = editInput.value; // Reset to current title
    });

    list.addEventListener('keydown', function (e) {
      if (!e.target.classList.contains('edit')) return;
      var li = e.target.closest('li');
      if (!li) return;
      var id = li.getAttribute('data-id');

      if (e.key === 'Enter' || e.keyCode === ENTER_KEY) {
        e.target.blur();
      } else if (e.key === 'Escape' || e.keyCode === ESCAPE_KEY) {
        li.classList.remove('editing');
        // Reset value to original title
        var todos = getTodos();
        for (var i = 0; i < todos.length; i++) {
          if (todos[i].id === id) {
            e.target.value = todos[i].title;
            break;
          }
        }
      }
    });

    list.addEventListener('blur', function (e) {
      if (!e.target.classList.contains('edit')) return;
      var li = e.target.closest('li');
      if (!li) return;
      li.classList.remove('editing');
      var id = li.getAttribute('data-id');
      updateTodo(id, e.target.value);
    }, true);

    // Toggle-all
    document.getElementById('toggle-all').addEventListener('change', function () {
      toggleAll(this.checked);
    });

    // Clear completed
    document.querySelector('.clear-completed').addEventListener('click', function () {
      clearCompleted();
    });

    // Hash change for routing
    window.addEventListener('hashchange', function () {
      render();
    });
  });
})();

const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('node:assert');

// ─── Given ───────────────────────────────────────────────────────────────────

Given('the app is loaded', function () {
  // The Before hook already loaded the app.
});

Given('the todo list is empty', function () {
  // The app is loaded fresh each scenario, so this is the default state.
});

Given('I have a todo titled {string}', function (title) {
  const todos = this.getTodos();
  const id = Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  todos.push({ id, title, completed: false });
  this.setTodos(todos);
  this.renderTodos();
});

Given('I have a completed todo titled {string}', function (title) {
  const todos = this.getTodos();
  const id = Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  todos.push({ id, title, completed: true });
  this.setTodos(todos);
  this.renderTodos();
});

Given('I have todos: {string}', function (commaSeparated) {
  const titles = commaSeparated.split(/,\s*/);
  const todos = this.getTodos();
  for (const title of titles) {
    const id = Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
    todos.push({ id, title, completed: false });
  }
  this.setTodos(todos);
  this.renderTodos();
});

Given('I have todos: {string}, {string}', function (t1, t2) {
  const todos = this.getTodos();
  for (const title of [t1, t2]) {
    const id = Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
    todos.push({ id, title, completed: false });
  }
  this.setTodos(todos);
  this.renderTodos();
});

Given('I have todos: {string}, {string}, {string}', function (t1, t2, t3) {
  const todos = this.getTodos();
  for (const title of [t1, t2, t3]) {
    const id = Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
    todos.push({ id, title, completed: false });
  }
  this.setTodos(todos);
  this.renderTodos();
});

Given('I have an active todo titled {string}', function (title) {
  const todos = this.getTodos();
  const id = Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  todos.push({ id, title, completed: false });
  this.setTodos(todos);
  this.renderTodos();
});

Given('I am editing the todo {string}', function (title) {
  const todos = this.getTodos();
  let todo = todos.find(t => t.title === title);
  if (!todo) {
    const id = Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
    todo = { id, title, completed: false };
    todos.push(todo);
    this.setTodos(todos);
    this.renderTodos();
  }
  const li = this.findTodoLi(title);
  if (li) {
    li.classList.add('editing');
    const editInput = li.querySelector('.edit');
    if (editInput) {
      editInput.value = title;
      editInput.focus();
    }
  }
});

// ─── When ────────────────────────────────────────────────────────────────────

When('I type {string} into the new-todo input', function (text) {
  const input = this.document.querySelector('.new-todo');
  assert.ok(input, 'new-todo input not found');
  input.value = text;
});

When('I press Enter', function () {
  const input = this.document.querySelector('.new-todo');
  assert.ok(input, 'new-todo input not found');
  const event = new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true });
  input.dispatchEvent(event);
});

When('I press Enter in the edit input', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(editInput, 'edit input not found');
  const event = new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true });
  editInput.dispatchEvent(event);
});

When('I press Escape in the edit input', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(editInput, 'edit input not found');
  const event = new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, which: 27, bubbles: true });
  editInput.dispatchEvent(event);
});

When('I click the toggle checkbox for {string}', function (title) {
  const li = this.findTodoLi(title);
  assert.ok(li, `todo "${title}" not found`);
  const toggle = li.querySelector('.toggle');
  assert.ok(toggle, `toggle not found for "${title}"`);
  toggle.click();
});

When('I click the {string} checkbox', function (id) {
  const checkbox = this.document.getElementById(id);
  assert.ok(checkbox, `#${id} checkbox not found`);
  checkbox.click();
});

When('I click {string}', function (text) {
  if (text === 'Clear completed') {
    const btn = this.document.querySelector('.clear-completed');
    assert.ok(btn, 'Clear completed button not found');
    btn.click();
    return;
  }
  const all = this.document.querySelectorAll('button, a, label, span, .clear-completed');
  for (const el of all) {
    if (el.textContent.trim() === text) { el.click(); return; }
  }
  assert.fail(`Element with text "${text}" not found`);
});

When('I complete all todos individually', function () {
  // Re-query after each click because re-render replaces DOM elements.
  let toggle = this.document.querySelector('.todo-list .toggle:not(:checked)');
  while (toggle) {
    toggle.click();
    toggle = this.document.querySelector('.todo-list .toggle:not(:checked)');
  }
});

When('I double-click the label for {string}', function (title) {
  const li = this.findTodoLi(title);
  assert.ok(li, `todo "${title}" not found`);
  const label = li.querySelector('label');
  assert.ok(label, `label not found for "${title}"`);
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

When('I change the edit input value to {string}', function (value) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(editInput, 'edit input not found');
  editInput.value = value;
});

When('the edit input loses focus', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(editInput, 'edit input not found');
  editInput.dispatchEvent(new this.window.FocusEvent('blur', { bubbles: true }));
});

When('I click the destroy button for {string}', function (title) {
  const li = this.findTodoLi(title);
  assert.ok(li, `todo "${title}" not found`);
  const destroy = li.querySelector('.destroy');
  assert.ok(destroy, `destroy button not found for "${title}"`);
  destroy.click();
});

When('I navigate to {string}', function (hash) {
  this.navigate(hash);
});

When('I complete the todo {string}', function (title) {
  const li = this.findTodoLi(title);
  assert.ok(li, `todo "${title}" not found`);
  const toggle = li.querySelector('.toggle');
  assert.ok(toggle, `toggle not found for "${title}"`);
  if (!toggle.checked) toggle.click();
});

When('I reload the app', function () {
  this.renderTodos();
});

// ─── Then ────────────────────────────────────────────────────────────────────

Then('there should be {int} todo in the list', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count, `Expected ${count} todo(s), found ${items.length}`);
});

Then('{string} should be hidden', function (selector) {
  const el = this.document.querySelector(selector);
  if (!el) return;
  const style = this.window.getComputedStyle(el);
  assert.ok(
    el.hidden || style.display === 'none' || this.hasClass(el, 'hidden'),
    `Expected ${selector} to be hidden`
  );
});

Then('I should see {int} todo in the list', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count, `Expected ${count} todo(s), found ${items.length}`);
});

Then('I should see {int} todos in the list', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count, `Expected ${count} todos, found ${items.length}`);
});

// I should see 0 todos in the list — handled by I should see {int} todos in the list

Then('the new-todo input should be cleared', function () {
  const input = this.document.querySelector('.new-todo');
  assert.ok(input, 'new-todo input not found');
  assert.strictEqual(input.value, '', 'Expected new-todo input to be cleared');
});

Then('the todo list should still be empty', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, 0, 'Expected todo list to be empty');
});

Then('the todo list should be empty', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, 0, 'Expected todo list to be empty');
});

Then('I should see a todo with title {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  let found = false;
  for (const li of items) {
    const label = li.querySelector('label');
    if (label && label.textContent.trim() === title) { found = true; break; }
  }
  assert.ok(found, `Expected to see a todo with title "${title}"`);
});

Then('the {string} todo should have class {string}', function (title, className) {
  const li = this.findTodoLi(title);
  assert.ok(li, `todo "${title}" not found`);
  assert.ok(this.hasClass(li, className), `Expected "${title}" to have class "${className}"`);
});

Then('the {string} todo should have its {string} property set', function (title, property) {
  const li = this.findTodoLi(title);
  assert.ok(li, `todo "${title}" not found`);
  if (property === 'completed') {
    const toggle = li.querySelector('.toggle');
    assert.ok(toggle, `toggle not found for "${title}"`);
    assert.ok(toggle.checked, `Expected "${title}" toggle to be checked`);
  }
});

Then('the {string} todo should not have class {string}', function (title, className) {
  const li = this.findTodoLi(title);
  assert.ok(li, `todo "${title}" not found`);
  assert.ok(!this.hasClass(li, className), `Expected "${title}" not to have class "${className}"`);
});

Then('all todos should be marked completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length > 0, 'No todos found');
  for (const li of items) {
    assert.ok(this.hasClass(li, 'completed'), 'Expected all todos to have class "completed"');
  }
});

Then('the {string} checkbox should be checked', function (id) {
  const checkbox = this.document.getElementById(id);
  assert.ok(checkbox, `#${id} checkbox not found`);
  assert.ok(checkbox.checked, `Expected #${id} to be checked`);
});

Then('the {string} button should be hidden', function (text) {
  const btn = this.document.querySelector('.clear-completed');
  if (!btn) return;
  const style = this.window.getComputedStyle(btn);
  assert.ok(btn.hidden || style.display === 'none',
    `Expected "${text}" button to be hidden`);
});

Then('the {string} todo item should have class {string}', function (title, className) {
  const li = this.findTodoLi(title);
  assert.ok(li, `todo "${title}" not found`);
  assert.ok(this.hasClass(li, className), `Expected "${title}" item to have class "${className}"`);
});

Then('the edit input for {string} should be focused', function (title) {
  const li = this.findTodoLi(title);
  assert.ok(li, `todo "${title}" not found`);
  assert.ok(li.querySelector('.edit:focus'), `Expected edit input for "${title}" to be focused`);
});

Then('the {string} todo item should not have class {string}', function (title, className) {
  const li = this.findTodoLi(title);
  // If the todo was renamed and no longer exists by that title, assertion is vacuously true.
  if (!li) return;
  assert.ok(!this.hasClass(li, className),
    `Expected "${title}" item not to have class "${className}"`);
});

Then('the todo-count should show {string}', function (expected) {
  const todoCount = this.document.querySelector('.todo-count');
  assert.ok(todoCount, 'todo-count element not found');
  assert.strictEqual(todoCount.textContent.trim(), expected,
    `Expected todo-count to show "${expected}", got "${todoCount.textContent.trim()}"`);
});

Then('the filter link for {string} should have class {string}', function (label, className) {
  const filters = this.document.querySelectorAll('.filters a');
  let found = false;
  for (const a of filters) {
    if (a.textContent.trim() === label) {
      assert.ok(this.hasClass(a, className),
        `Expected filter "${label}" to have class "${className}"`);
      found = true;
      break;
    }
  }
  assert.ok(found, `Filter "${label}" not found`);
});

Then('localStorage should contain a key matching {string}', function (pattern) {
  const keys = Object.keys(this.localStorage);
  const regex = new RegExp(pattern);
  const matched = keys.some(k => regex.test(k));
  assert.ok(matched, `Expected localStorage key matching "${pattern}", keys: ${keys.join(', ')}`);
});

Then('localStorage todo data should include fields {string}, {string}, {string}', function (f1, f2, f3) {
  const fields = [f1, f2, f3];
  const keys = Object.keys(this.localStorage);
  const todoKey = keys.find(k => k.startsWith('todos-'));
  assert.ok(todoKey, 'No todos-* key found in localStorage');
  let data;
  try {
    data = JSON.parse(this.localStorage.getItem(todoKey));
  } catch (e) {
    assert.fail(`localStorage data under "${todoKey}" is not valid JSON`);
  }
  assert.ok(Array.isArray(data), 'localStorage todo data should be an array');
  assert.ok(data.length > 0, 'localStorage todo data should have at least one item');
  for (const item of data) {
    for (const field of fields) {
      assert.ok(Object.prototype.hasOwnProperty.call(item, field),
        `Expected item to have field "${field}"`);
    }
  }
});

Then('localStorage todo data should include fields {string}', function (fieldString) {
  const fields = fieldString.split(/,\s*/);
  const keys = Object.keys(this.localStorage);
  const todoKey = keys.find(k => k.startsWith('todos-'));
  assert.ok(todoKey, 'No todos-* key found in localStorage');
  let data;
  try {
